// Mirror of backend/assistant/pii.js detectPII() — CPU-only, no GPU.
const text = String($json.message || '');
const EMAIL_RE = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g;
const PHONE_RE = /(?:\+\d{1,3}[\s.-]?)?\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4}\b/g;
const CARD_RE = /\b(?:\d[ -]?){13,19}\b/g;
const INTENT_RE = /\bmy\s+(order|orders|receipt|profile|account|address|email|phone|card|payment)\b|\bwhere\s+is\s+my\b|\b(track|cancel|return|resend)\s+my\b/gi;
function luhn(s){const d=String(s).replace(/\D/g,'');if(d.length<13||d.length>19)return false;let sum=0,alt=false;for(let i=d.length-1;i>=0;i--){let n=+d[i];if(alt){n*=2;if(n>9)n-=9;}sum+=n;alt=!alt;}return sum%10===0;}
const types = [];
if (EMAIL_RE.test(text)) types.push('email');
if (PHONE_RE.test(text)) types.push('phone');
for (const m of text.matchAll(CARD_RE)) { if (luhn(m[0])) { types.push('card'); break; } }
if (INTENT_RE.test(text)) types.push('intent');
const hasPII = types.length > 0;
return [{ json: { message: text, hasPII, types, target: hasPII ? 'local' : 'cloud', reason: hasPII ? ('LOCAL — detected ' + types.join(', ') + '; must stay on-device (no leak to cloud).') : 'CLOUD — no PII and no private-data intent; public catalog question.' } }];
